@ConfigurationProperties("l012")
public record DispersionProperties(Duration espera, int bloqueDefault,
                                   Map<String, Integer> bloquePorEquipo,
                                   int csiDestinoDefault,
                                   Map<String, Integer> csiDestinoPorEquipo) {

    /** STR_EQUIPO viene de CSIID (librería SOPORTE); en Java, del nombre del nodo. */
    public int csiDestino(String equipo) {
        return csiDestinoPorEquipo.getOrDefault(equipo.strip(), csiDestinoDefault);
    }

    /** TRANS_X_SEG := BLOCK_ENVIOS / TMPO_ESPERA, solo informativo. */
    public long transaccionesPorSegundo(int bloque) {
        return bloque / Math.max(1, espera.toSeconds());
    }
}

@Component
@RequiredArgsConstructor
public class SalvoBuenCobroPolicy {

    private final SbcProperties sbc;   // l012.sbc.claves: [3009, 3036, 2005, 2006, 2007]
                                       // l012.sbc.claves-post-liberacion: [2005, 2006, 2007]

    /**
     * VALIDA_CVE(CVE, ECTA, CONTA). ECTA y CONTA se reciben en la macro pero no intervienen.
     * Fuera del ciclo SBC se excluyen las claves SBC; durante el ciclo solo pasan ellas;
     * ya liberado el SBC, las tres claves de cargo vuelven a ser elegibles.
     */
    public boolean admite(int clave, EstadoSbc estado) {
        boolean esSbc = sbc.claves().contains(clave);
        if (!estado.liberandoSbc() && !esSbc) {
            return true;
        }
        if (estado.liberandoSbc() && esSbc) {
            return true;
        }
        return estado.sbcLiberado() && sbc.clavesPostLiberacion().contains(clave);
    }
}

/** LIB_SBC y SBC_LIBERADO: estado de la tarea de control, no globales. */
public record EstadoSbc(boolean liberandoSbc, boolean sbcLiberado) {}

@Component
@RequiredArgsConstructor
public class ElegibilidadMovimiento {

    private static final Set<Integer> CARGO_POR_CLAVE = Set.of(2005, 2006, 2007);
    private final CatalogoClaves catalogo;          // ACLAVES, cargado de S080 con L710_CONSUL_DETALLE
    private final SalvoBuenCobroPolicy sbc;

    /** Primer IF de ENVIA_MOVIMIENTOS: tipo de proceso, función 1 e indicador de envío CitiDirect. */
    public boolean movimientoElegible(MovimientoCaptacion m) {
        return m.tipoProceso() < 20
                && m.funcion() == 1
                && (m.indicadorEnvioCd() == 2 || m.indicadorEnvioCd() == 3);   // ISOLATION BNE 2023 R10
    }

    /** WHILE INDICE < 6 AND CLAVE_BNX > 0: ocurrencias 1..5, se corta en la primera clave 0. */
    public List<OcurrenciaCitiDirect> ocurrencias(MovimientoCaptacion m, EstadoSbc estado) {
        var salida = new ArrayList<OcurrenciaCitiDirect>();
        for (var oc : m.ocurrencias()) {                     // ya limitado a 5
            if (oc.clave() <= 0) break;
            var cat = catalogo.get(oc.clave());
            if (cat.indicadorCiti() != 1 && cat.indicadorCiti() != 2) continue;   // descarte silencioso
            if (!sbc.admite(oc.clave(), estado)) continue;
            boolean cargo = cat.afectacionContable() == 1 || CARGO_POR_CLAVE.contains(oc.clave());
            salida.add(new OcurrenciaCitiDirect(oc.indice(), oc.clave(), cargo,
                    oc.importe()));                          // IDFENT_OCUR + IDFDEC_OCUR -> BigDecimal escala 2
        }
        return salida;
    }
}

/** Tipo de movimiento SWIFT del tag :61: según alta o eliminación y cargo o abono. */
public enum IndicadorMovimiento {
    DR, CR, RD, RC;

    static IndicadorMovimiento de(int statusMovimiento, boolean cargo) {
        boolean alta = statusMovimiento == 1;           // IDFSTATUS = 1; cualquier otro valor es eliminación
        if (alta) return cargo ? DR : CR;
        return cargo ? RD : RC;
    }
}

@Component
@RequiredArgsConstructor
public class DetalleMt942Builder {

    private final IdentificacionMt942Builder identificacion;   // ARMA_ID_942: header PRISM y :25:
    private final Tag61Builder tag61;                           // ARMA_TAG61 + ANALIZA

    public void arma(Mt942Builder msg, MovimientoCaptacion m, OcurrenciaCitiDirect oc) {
        String moneda = (m.moneda() == 1) ? "MXN" : "USD";     // cualquier moneda distinta de 1 sale como USD
        LocalDate fechaValor = (m.fechaValor() != null)
                ? m.fechaValor()
                : m.fechaContable();                           // IDFFECVAL = 0 -> IDFECONT
        identificacion.arma(msg, m, moneda);
        tag61.arma(msg, m, oc, fechaValor, IndicadorMovimiento.de(m.status(), oc.cargo()));
    }
}

@Entity
@Table(name = "ctl_envio_citidirect")       // S151B04CTLCITIDIR
@IdClass(ControlEnvioId.class)
public class ControlEnvioCitiDirect {
    @Id int sistema;                          // B04-CID-SISTEMA (500 o 264)
    @Id LocalDate fechaEnvio;                 // B04-CID-FECENV
    @Id long ctlFile;                         // B04-CID-CTLFILE: registro físico del archivo
    @Id long ctlEnvio;                        // B04-CID-CTLENVIO: número de mensaje
    @Id int autAsiento;                       // B04-CID-AUTASIENTO: índice de ocurrencia
    @Id long autS151;                         // B04-CID-AUTS151
    int horaEnvio;                            // B04-CID-HORENV HHMMSS
    @Column(length = 16) String nio;          // alfanumérico: VARCHAR(16), nunca número
    int estatus;                              // 0 creado, 99 depositado, n+10 error TCP, 1/2/3 TANDEM
    int reintentos;
}

@Service
@RequiredArgsConstructor
public class BitacoraEnvios {
    private final ControlEnvioRepository repo;

    /** Devuelve false si el STORE falló (CREA_BIFIN := 1); el llamador reintenta. */
    @Transactional
    public boolean crea(ControlEnvioId id, String nio, LocalTime hora) {
        if (repo.existsById(id)) {
            return true;                      // FIND encontrado: no se duplica
        }
        try {
            repo.save(ControlEnvioCitiDirect.nuevo(id, nio, hora));   // ESTATUS 0, REINTENTOS 0
            return true;
        } catch (DataAccessException e) {
            log.error("ERR CREAT 01 CAT. {} # MSG {}", e.getMessage(), id.ctlEnvio());
            return false;
        }
    }
}

@MessagingGateway(defaultRequestChannel = "tcpCarrierOut")
public interface TcpCarrierGateway {
    /** DEPOSITAR(TXTSZ, MSG, SCRATCHARRAY) de SHELL/SOPORTECOMS: 0 = aceptado por el carrier. */
    int depositar(byte[] mensajeConCabecera);
}

@Component
@RequiredArgsConstructor
public class DespachadorMt942 {

    private final TcpCarrierGateway carrier;
    private final BitacoraEnvios bitacora;
    private final AtomicBoolean desligaTcp = new AtomicBoolean();   // DESLIGA_TCP

    void deposita(Mensaje942 msg, boolean reenvioPorHi, boolean liberandoSbc) {
        int resultado = carrier.depositar(msg.conCabecera());        // HDR_LEN_MSG ya rellenado
        int estatus = (resultado > 0) ? resultado + 10 : 99;
        if (!reenvioPorHi) {
            bitacora.actualizaEstatus(msg.fechaProceso(), msg.numMensaje(), estatus);   // ACTZA_BIFIN(0, ...)
        }
        if (estatus == 12 && !liberandoSbc) {
            desligaTcp.set(true);         // corta el ciclo de lectura hasta el siguiente evento
            metricas.erroresTcp().increment();
        }
    }
}

/** ENVIA_CD(RSTL, NUM_SEC): punto de entrada que invoca P012 con la respuesta de TANDEM. */
@Service
@RequiredArgsConstructor
public class RespuestaTandemService {

    private final BitacoraEnvios bitacora;
    private final EstadoDespacho despacho;      // ULTIMO_MSG_ENV, RECHAZADO

    @Transactional
    public void enviaCd(int resultado, int numSecuencia, LocalDate fechaProceso) {
        if (numSecuencia > despacho.ultimoMensajeEnviado()) {
            // El ALGOL solo descarta si además está prendido el monitor; aquí se descarta siempre.
            metricas.respuestaFueraDeRango().increment();
            log.warn("Secuencia {} mayor a la última enviada {}", numSecuencia,
                     despacho.ultimoMensajeEnviado());
            return;
        }
        switch (resultado) {
            case 1 -> bitacora.actualizaEstatus(fechaProceso, numSecuencia, 1);      // aceptado
            case 2 -> {                                                                  // rechazado
                despacho.marcaRechazo();                                                 // RECHAZADO := TRUE
                bitacora.actualizaEstatus(fechaProceso, numSecuencia, 2);
            }
            case 3, 4 -> bitacora.actualizaEstatus(fechaProceso, numSecuencia, 3);   // duplicado
            default -> metricas.respuestaNoContemplada(resultado).increment();       // sin cambio de estatus
        }
    }
}

@Component
@RequiredArgsConstructor
public class ReenvioBitacora {

    private static final Set<Integer> REENVIABLES = Set.of(12, 11, 2, 0, 99);   // "ERROR EN TRANSF."
    private final ControlEnvioRepository repo;
    private final DespachadorMt942 despachador;
    private final ReenvioProperties props;      // l012.reenvio.ciclos-sin-respuesta: 150, pausa: 20s, max-reintentos

    /** Se dispara al completar 150 ciclos (TOT_ENVIOS) o cuando ENVIA_CD reportó un rechazo. */
    @Transactional
    public void reenvia(LocalDate fechaProceso, int sistema, int bloque) throws InterruptedException {
        Thread.sleep(props.pausa().toMillis());                      // WAIT((20))
        int enBloque = 0;
        try (Stream<ControlEnvioCitiDirect> pendientes =
                 repo.streamByFechaEnvioOrderByCtlEnvio(fechaProceso)) {   // SET B04SXCTLENVIO
            for (var reg : (Iterable<ControlEnvioCitiDirect>) pendientes::iterator) {
                if (despachador.desligado()) break;
                if (!REENVIABLES.contains(reg.estatus())) continue;
                if (reg.reintentos() >= props.maxReintentos()) {     // no existe en el ALGOL
                    alertas.intervencionManual(reg);
                    continue;
                }
                despachador.reenvia(reg);                            // relee el registro físico CTLFILE
                reg.incrementaReintentos();                          // ACTZA_BIFIN(1, REINTENTOS, ...)
                if (++enBloque >= bloque) { enBloque = 0; Thread.sleep(1_000); }
            }
        }
    }
}
